package com.bank.fraud;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class UnionFindDemo {

    private static final Logger log = Logger.getLogger(UnionFindDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // 5 accounts indexed 0..4
        AccountGroups groups = new AccountGroups(5);

        groups.union(0, 1);   // accounts 0 and 1 linked
        groups.union(2, 3);   // accounts 2 and 3 linked

        log.info(() -> "0 and 3 connected? " + groups.connected(0, 3)); // false

        groups.union(1, 2);   // merges {0,1} and {2,3}

        log.info(() -> "0 and 3 connected? " + groups.connected(0, 3)); // true
        log.info(() -> "distinct fraud rings: " + groups.count());       // 2 (ring + lone 4)
    }
}

// ─── Would be in service/AccountGroups.java in a real project ───
class AccountGroups {

    private static final Logger log = Logger.getLogger(AccountGroups.class.getName());

    private final int[] parent;
    private final int[] rank;
    private int count;              // number of disjoint sets

    AccountGroups(int n) {
        parent = new int[n];
        rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;  // each its own set
        count = n;
    }

    // Find with path compression: re-point nodes directly to root.
    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    // Union by rank: attach shorter tree under taller.
    void union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;                 // already same set
        if (rank[ra] < rank[rb]) {
            parent[ra] = rb;
        } else if (rank[ra] > rank[rb]) {
            parent[rb] = ra;
        } else {
            parent[rb] = ra;
            rank[ra]++;
        }
        count--;
        log.fine(() -> "  merged groups → " + count + " remain");
    }

    boolean connected(int a, int b) {
        return find(a) == find(b);
    }

    int count() {
        return count;
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
